    listen('periodCalendar','change',()=>primeCalendarChanged('periodCalendar','periodSelector',{required:true,refresh:true}));listen('compareCalendar','change',()=>primeCalendarChanged('compareCalendar','compareSelector',{refresh:true}));listen('manualPeriodCalendar','change',()=>primeCalendarChanged('manualPeriodCalendar','manualPeriod',{required:true}));listen('manualPeriod','change',()=>syncPrimeCalendar('manualPeriod','manualPeriodCalendar'));listen('detailCloseTop','click',()=>{const d=$('detailDialog');if(d?.open)d.close();});listen('saveDetailInsight','click',savePrimeInsight);listen('openSavedInsights','click',openSavedInsights);listen('exportDetailData','click',exportPrimeDetail);listen('shareDetailWhatsApp','click',()=>sharePrimeDetail('whatsapp'));listen('screenshotDetail','click',()=>sharePrimeDetail('screenshot'));document.querySelectorAll('[data-detail-tab]').forEach(b=>b.addEventListener('click',()=>applyPrimeDetailTab(b.dataset.detailTab)));installPrimeDetailEnhancements();$('detailDialog')?.addEventListener('close',()=>{state.detailCompareOverride='';state.activeDetail=null;Object.entries(state.charts).forEach(([id,c])=>{if(/detail|Interactive/i.test(id)){try{c.destroy();}catch(_){}delete state.charts[id];}});});listen('themeToggle','click',toggleTheme); listen('refreshBtn','click',()=>refreshCurrent(true));
    listen('globalSearchBtn','click',openCommandPalette); listen('dashboardModeToggle','click',toggleDashboardMode);
    ['auditTable','costTable','moversTable'].forEach(id=>{const table=$(id);table?.querySelector('thead')?.addEventListener('click',e=>{const th=e.target.closest('th');if(th)sortTableByHeader(table,th);});}); listen('notificationBtn','click',openNotificationCenter); listen('workspaceBtn','click',openWorkspace); listen('mobileMoreBtn','click',()=>{const open=document.body.classList.toggle('nav-open');$('menuToggle')?.setAttribute('aria-expanded',String(open));}); listen('anomalySettingsBtn','click',openAnomalySettings); listen('anomalySettingsForm','submit',saveAnomalySettings); listen('resetAnomalyThresholds','click',resetAnomalyThresholds); listen('refreshAuditTrail','click',loadAuditTrail); listen('globalSearchInput','input',renderGlobalSearch); listen('globalSearchInput','keydown',handleGlobalSearchKeys); listen('saveCurrentView','click',saveCurrentView); listen('clearNotifications','click',clearNotifications); listen('openAuditFromInsight','click',()=>showPage('audit'));
    document.querySelectorAll('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.closeDialog)?.close()));
    document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommandPalette();} if(e.key==='Escape'){document.body.classList.remove('nav-open');$('menuToggle')?.setAttribute('aria-expanded','false');}});
    listen('kpiGrid','click',e=>{const fav=e.target.closest('[data-favorite-kpi]');if(fav){e.stopPropagation();toggleFavoriteKpi(fav.dataset.favoriteKpi);return;}});
    listen('periodSelector','change',()=>{syncPrimeCalendar('periodSelector','periodCalendar');setBusy('Mengganti periode dan menghitung ulang…');invalidateCache();Promise.resolve(refreshCurrent(true)).finally(clearBusy);}); listen('compareSelector','change',()=>{syncPrimeCalendar('compareSelector','compareCalendar');setBusy('Memperbarui periode pembanding…');invalidateCache();Promise.resolve(refreshCurrent(true)).finally(clearBusy);});
