    listen('dismissNotice','click',()=>{const notice=$('dataNotice');if(notice)notice.hidden=true;});
    listen('rbbSearch','input',filterRBB); listen('auditSearch','input',()=>{state.auditPage=0;renderAudit();}); listen('auditDirection','change',()=>{state.auditPage=0;renderAudit();}); listen('auditMateriality','change',()=>{state.auditPage=0;renderAudit();}); listen('auditPrev','click',()=>{state.auditPage=Math.max(0,(state.auditPage||0)-1);renderAudit();}); listen('auditNext','click',()=>{state.auditPage=(state.auditPage||0)+1;renderAudit();}); listen('auditSearchClear','click',()=>{$('auditSearch').value='';state.auditPage=0;renderAudit();$('auditSearch').focus();});listen('auditFiltersToggle','click',()=>{const box=$('auditAdvancedFilters'),open=box.hidden;box.hidden=!open;$('auditFiltersToggle').setAttribute('aria-expanded',String(open));});document.querySelectorAll('[data-audit-quick]').forEach(b=>b.addEventListener('click',()=>{const kind=b.dataset.auditQuick; if(kind==='up')$('auditDirection').value='up';else if(kind==='down')$('auditDirection').value='down';else $('auditMateriality').value='1000000000';document.querySelectorAll('[data-audit-quick]').forEach(x=>x.classList.toggle('active',x===b));state.auditPage=0;renderAudit();}));document.querySelectorAll('[data-chart-detail]').forEach(card=>{const open=()=>openChartCardDetail(card.dataset.chartDetail);card.addEventListener('click',open);card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}});}); listen('costSearch','input',renderCosts);listen('costSearchClear','click',()=>{$('costSearch').value='';renderCosts();$('costSearch').focus();});listen('costFiltersToggle','click',()=>{const box=$('costAdvancedFilters'),open=box.hidden;box.hidden=!open;$('costFiltersToggle').setAttribute('aria-expanded',String(open));});listen('costDirection','change',renderCosts);listen('costMateriality','change',renderCosts);document.querySelectorAll('[data-cost-quick]').forEach(b=>b.addEventListener('click',()=>{const k=b.dataset.costQuick;if(k==='up')$('costDirection').value='up';else if(k==='down')$('costDirection').value='down';else $('costMateriality').value='1000000000';document.querySelectorAll('[data-cost-quick]').forEach(x=>x.classList.toggle('active',x===b));renderCosts();}));document.querySelectorAll('[data-dashboard-detail]').forEach(card=>{const open=()=>openDashboardInteractive(card.dataset.dashboardDetail);card.addEventListener('click',open);card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}});});document.addEventListener('click',e=>{const target=e.target.closest('[data-target-popup-label]');if(target){loadDetailTrend({label:target.dataset.targetPopupLabel});}});
    document.querySelectorAll('[data-export-table]').forEach(b=>b.addEventListener('click',()=>exportTable(b.dataset.exportTable)));
    document.querySelectorAll('[data-report]').forEach(b=>b.addEventListener('click',()=>buildReport(b.dataset.report)));
    listen('exportExecutive','click',()=>{buildReport('executive');setTimeout(()=>window.print(),150)}); listen('printReport','click',()=>window.print()); listen('downloadReportCsv','click',downloadReportCsv);
    listen('runSimulation','click',runSimulation); listen('fileUpload','change',e=>readImportFile(e.target.files?.[0]));document.querySelectorAll('[data-scenario]').forEach(b=>b.addEventListener('click',()=>applyScenarioPreset(b.dataset.scenario)));document.querySelectorAll('[data-report-check]').forEach(b=>b.addEventListener('change',updateReportReadiness));updateReportReadiness();
    listen('uploadZone','dragover',e=>{e.preventDefault();$('uploadZone')?.classList.add('dragging')}); listen('uploadZone','dragleave',()=>$('uploadZone')?.classList.remove('dragging')); listen('uploadZone','drop',e=>{e.preventDefault();$('uploadZone')?.classList.remove('dragging');readImportFile(e.dataTransfer.files?.[0])});
    listen('confirmImport','click',confirmImport); listen('cancelImport','click',cancelImport); listen('reloadDatabase','click',loadDatabase); listen('manualForm','submit',saveManual); listen('reloadManual','click',loadManual); listen('loadTargets','click',loadTargets); listen('saveTargets','click',saveTargets);
    document.addEventListener('focusin',e=>{const el=e.target.closest('.rupiah-target-input');if(el){el.value=String(parseRupiahInput(el.value)||'');setTimeout(()=>el.select(),0);}});
    document.addEventListener('focusout',e=>{const el=e.target.closest('.rupiah-target-input');if(el)el.value=formatRupiahInput(parseRupiahInput(el.value));});
    document.addEventListener('click',e=>{const b=e.target.closest('[data-intel-detail],[data-mover-detail],[data-report-detail]');if(!b)return; e.preventDefault();openInteractiveDetail({label:b.dataset.detailLabel||'',gl:b.dataset.detailGl||'',desc:b.dataset.detailDesc||'',value:b.dataset.detailValue===''?null:b.dataset.detailValue,previous:b.dataset.detailPrevious===''?null:b.dataset.detailPrevious,diff:b.dataset.detailDiff===''?null:b.dataset.detailDiff,pctValue:b.dataset.detailPct===''?null:b.dataset.detailPct,source:b.dataset.detailSource|| (b.hasAttribute('data-report-detail')?'Laporan Eksekutif':b.hasAttribute('data-mover-detail')?'Market Volatility':'Financial Intelligence')});}); listen('actionForm','submit',saveAction);
