  async function loadDetailTrend({label='',gl='',desc=''}={}){
    state.activeDetail={label,gl,desc};
    const d=$('detailDialog'); const title=gl?`Tren Saldo Akun — ${gl}`:`Rincian KPI — ${label}`;
    openDetailShell(title);
    setBusy('Memuat histori saldo dan grafik…');
    try{
      const data=await api('getDetailTrend',{p1:period(),p2:state.detailCompareOverride||comparePeriod(),p3:gl,p4:label},'GET',{force:true,ttl:0,timeout:45000});
      const k=state.kpi.find(x=>x.label===label);
      const rows=gl?(state.xray||[]).filter(x=>String(x.gl)===String(gl)):[];
      const curr=gl?(rows[0]?.curr??data.current):(k?.val??data.current);
      const prev=gl?(rows[0]?.prev??data.previous):(k?.prev??data.previous);
      const diff=Number(curr||0)-Number(prev||0);
      const breakdown=(data.breakdown||[]);
      const breakdownCards=breakdown.length?`<div class="detail-section-title"><h4>Komposisi nilai</h4><span class="muted">Periode ${escapeHTML(period()||'—')}</span></div><div class="detail-breakdown">${breakdown.map(x=>`<div class="detail-breakdown-card"><span>${escapeHTML(x.label)}</span><strong>${idr(x.value)}</strong></div>`).join('')}</div>${label==='KREDIT'?'<p class="muted">Klasifikasi konsumtif/produktif didasarkan pada kata kunci nama akun yang tersedia. Saldo yang tidak dapat diklasifikasikan ditampilkan sebagai “Lainnya / belum terklasifikasi”; verifikasi terhadap mapping resmi sebelum digunakan sebagai angka pelaporan.</p>':''}<div class="detail-chart-wrap"><canvas id="detailBreakdownChart" aria-label="Grafik komposisi nilai" role="img"></canvas></div>`:'<p class="muted">Komponen terperinci tidak tersedia dari mapping akun saat ini.</p>';
      $('detailContent').innerHTML=`<div class="summary-list"><div class="summary-row"><span>Periode data</span><strong>${escapeHTML(period()||'—')}</strong></div><div class="summary-row"><span>Nilai saldo</span><strong>${idr(curr)}</strong></div><div class="summary-row"><span>Periode pembanding</span><strong>${escapeHTML(comparePeriod()||'—')}</strong></div><div class="summary-row"><span>Nilai pembanding</span><strong>${idr(prev)}</strong></div><div class="summary-row"><span>Selisih</span><strong class="${diff>=0?'positive':'negative'}">${idr(diff)}</strong></div><div class="summary-row"><span>Perubahan</span><strong>${prev?pct(diff/Math.abs(Number(prev))*100):'—'}</strong></div>${gl?`<div class="summary-row"><span>Nama akun</span><strong>${escapeHTML(desc||rows[0]?.desc||'—')}</strong></div>`:`<div class="summary-row"><span>Target</span><strong>${Number(k?.target)?idr(k.target):'Belum ditetapkan'}</strong></div><div class="summary-row"><span>Pencapaian</span><strong>${pct(k?.ach)}</strong></div>`}</div><div class="detail-section-title"><h4>Tren historis saldo</h4><span class="muted">${(data.periods||[]).length} periode tersedia · rentang minimal 12 bulan atau sampai tanggal pembanding</span></div><div class="detail-chart-wrap"><canvas id="detailTrendChart" aria-label="Grafik tren saldo historis" role="img"></canvas></div>${breakdownCards}<p class="muted">Sumber: DATA_NERACA. Grafik hanya menggunakan periode yang benar-benar tersedia; apabila data historis kurang dari 12 bulan, seluruh periode yang tersedia ditampilkan.</p>`;
      renderDetailLineChart('detailTrendChart',data,gl?`${gl} — ${desc}`:label);
      if(breakdown.length)renderDetailBreakdown('detailBreakdownChart',breakdown);
      labelTableCells($('detailContent'));
    }catch(e){
      $('detailContent').innerHTML=`<div class="empty-state"><strong>Grafik belum dapat dimuat.</strong><p>${escapeHTML(e.message||'Terjadi kesalahan saat memuat histori.')}</p><p class="muted">Pastikan backend Apps Script sudah diperbarui ke versi yang menyediakan aksi getDetailTrend.</p><button type="button" class="btn btn-secondary" id="retryDetailTrend">Coba lagi</button></div>`;
      $('retryDetailTrend')?.addEventListener('click',()=>loadDetailTrend({label,gl,desc}));
    }finally{clearBusy();}
  }
